import "dotenv/config";
import { PrismaPg } from "@prisma/adapter-pg";
// Generated by `prisma generate` (prisma/schema.prisma `generator client`
// block, Prisma 7's "prisma-client" generator) — not committed, not present
// until that command runs. It could not be generated in the sandbox that
// authored this file: this environment's network policy blocks
// binaries.prisma.sh, so `prisma generate` fails fetching the schema-engine
// binary (docs/08-execution-plan.md §16, E2-01 progress note). Run
// `pnpm db:generate` (or `pnpm install`, which triggers it via the `prisma`
// postinstall) with normal internet access — CI, Vercel, or a dev machine —
// before importing this module; verify the entry file name below still
// matches what Prisma actually writes to src/generated/client/.
import { PrismaClient } from "./generated/client/client.js";

/**
 * Builds a new Prisma Client for the given connection string, through the
 * @prisma/adapter-pg driver adapter (02-architecture.md §4, §9). Callers
 * with their own validated config — `apps/api`'s Fastify plugin
 * (plugins/prisma.ts), E2-05 — call this directly with `config.DATABASE_URL`
 * rather than using `getPrisma()` below, so the client actually reflects
 * that config instead of a separate `process.env` read. Always pass the
 * **pooled** URL (Neon `DATABASE_URL`), never `DIRECT_URL` — that one is
 * for the CLI (`prisma.config.ts`); DDL and advisory locks don't work
 * through the pooled endpoint.
 */
export function createPrismaClient(connectionString: string): PrismaClient {
  if (!connectionString) {
    throw new Error("A connection string is required to create the Prisma client.");
  }
  const adapter = new PrismaPg({ connectionString });
  return new PrismaClient({ adapter });
}

// Lazily-built, process-wide client for scripts and callers with no config
// object of their own (seed.ts, ad-hoc usage) — reads `DATABASE_URL` from
// `process.env` only when first actually requested, **not** at import time.
// Deferring that read matters: this module is reachable just by importing
// anything from the `database` package (its index.ts re-exports from here),
// and ES modules run their top-level code on import regardless of which
// named export is used — an eager `process.env.DATABASE_URL` read at module
// load would throw for any caller that only wanted, say, `createPrismaClient`
// or a type, in a process that never set that variable (e.g. a unit test
// that injects a fake Prisma client and has no real database at all).
//
// Cached on `globalThis` so `tsx watch`/dev-server hot-reload reuses the
// existing client across reloads instead of opening a fresh pool each time
// and eventually exhausting Neon's pooled connection limit (same pattern
// Prisma recommends for Next.js dev servers).
declare global {
  var __cupcakePrisma: PrismaClient | undefined;
}

export function getPrisma(): PrismaClient {
  if (globalThis.__cupcakePrisma) {
    return globalThis.__cupcakePrisma;
  }
  const connectionString = process.env.DATABASE_URL;
  if (!connectionString) {
    throw new Error(
      "DATABASE_URL is required to create the Prisma client (02-architecture.md §9).",
    );
  }
  const client = createPrismaClient(connectionString);
  if (process.env.NODE_ENV !== "production") {
    globalThis.__cupcakePrisma = client;
  }
  return client;
}

export type { PrismaClient } from "./generated/client/client.js";
